import{_ as t,o,c as r,ae as a}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"Resource hierarchy via untyped recursive nodes","description":"","frontmatter":{"id":"4761776210","title":"Resource hierarchy via untyped recursive nodes","state":"Approved","created":"2026-07-09T00:00:00.000Z","tags":["multi-tenancy","hierarchy","authorization","platform-design"],"category":"Platform"},"headers":[],"relativePath":"adrs/4761776210/README.md","filePath":"adrs/4761776210/README.md"}'),n={name:"adrs/4761776210/README.md"};function i(s,e,d,h,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="resource-hierarchy-via-untyped-recursive-nodes" tabindex="-1">Resource hierarchy via untyped recursive nodes <a class="header-anchor" href="#resource-hierarchy-via-untyped-recursive-nodes" aria-label="Permalink to &quot;Resource hierarchy via untyped recursive nodes&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Platforms that host resources for organizations (agents, schedules, skills, policies) must answer &quot;where does this resource live?&quot; before they can answer who sees it, who may use it, and which rules apply to it.</p><p>Three concerns are distinct questions, though they are not independent:</p><table tabindex="0"><thead><tr><th>Concern</th><th>Question</th></tr></thead><tbody><tr><td>Tenant</td><td>Which isolation wall is this inside?</td></tr><tr><td>Position</td><td>Which node of the tenant&#39;s hierarchy is it attached to?</td></tr><tr><td>Ownership</td><td>Which principal answers for it?</td></tr></tbody></table><p>Position is the governed one. Attaching a resource to a node is an authorized write: the authorization system decides whether the calling principal may attach there, and the principal accountable for that node is accountable for everything under it. Ownership therefore has an answer the moment position does, which is why this ADR does not require every resource to carry an owner of its own.</p><p>A note on vocabulary, because three words for one concept caused repeated confusion. The element of the tree is a <strong>node</strong>, the tree is the tenant&#39;s <strong>hierarchy</strong>, and putting a resource at a node is <strong>attaching</strong> it. This ADR previously said &quot;place&quot; and &quot;container&quot; for the node and &quot;placement&quot; for the attachment; those words are retired. &quot;Place&quot; invited a containment reading that the design denies, since nothing is stored inside a node, and &quot;placement&quot; already means workload scheduling and topology in cloud vocabulary (EC2 placement groups, proximity placement groups, compute placement policies, pod placement). &quot;Container&quot; was rejected for colliding with OCI containers by <a href="./../6310044131/README.html">ADR#6310044131</a>, which applied that same collision test to the field name.</p><h3 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h3><p><strong>Enumerated levels.</strong> An enum such as <code>org | project | user</code> on every resource. Rejected: it encodes our guess about the tenant&#39;s org chart. One company organizes by teams inside departments, another by client accounts, another is a solo operator. Every mismatch becomes a schema migration or a workaround.</p><p><strong>Flat namespaces plus labels</strong> (the Kubernetes shape). Rejected: no native shadowing or policy inheritance, so hierarchy gets reinvented badly on top. Kubernetes itself needed the Hierarchical Namespace Controller bolted on later.</p><p><strong>Pure relations, no canonical parent</strong> (the raw Zanzibar shape). Rejected as the hierarchy: resources lose a single unambiguous home, and &quot;which <code>pr-reviewer</code> do I get here?&quot; has no defined answer. Relations remain the right substrate for membership.</p><p><strong>Structure encoded in the string (paths or prefixes).</strong> A position expressed as a path such as <code>acme/backend/ml</code>: walk-up is segment-stripping, flow-down is prefix matching, and no tree needs to exist. Rejected: a rename or move invalidates every pointer (unrepairable wherever history is immutable; with opaque ids a single recorded move rearranges everything and no pointer changes); there is no authoritative structure to validate against, so a typo silently mints a phantom branch and restructures leave no audit trail; and policy bound to a prefix detaches silently on rename. The chosen design keeps the pointer an opaque string and moves the structure into audited tree operations.</p><p><strong>Multiple parents per resource.</strong> Rejected: a position exists to answer which policy chain governs a resource and where name resolution starts; two parents give two ceilings and two shadowing orders with no defined winner. All three clouds are single-parent for the same reason (AIP-124: at most one canonical parent). The need to appear in several groupings is served by labels (unlimited), and cross-node access by shares; one parent for governance, many labels for queries.</p><p><strong>A node entity with fields.</strong> Two drafts died under review: <code>{ id, tenant, parentId?, kind, name }</code> (tenant is derivable, kind is an uninterpreted label, name is an API-surface slug) and then <code>{ id, parentId? }</code> (the parent is not a node property: commands that change the tree validate tree-wide invariants, so the tree is the consistency unit, not the node).</p><h3 id="what-the-industry-converged-on" tabindex="-1">What the industry converged on <a class="header-anchor" href="#what-the-industry-converged-on" aria-label="Permalink to &quot;What the industry converged on&quot;">​</a></h3><p>All three major clouds faced unknown tenant structure and independently built the same shape:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Wall</th><th>Untyped recursive middle</th><th>Promoted leaf</th><th>Rules flow down as</th></tr></thead><tbody><tr><td>Google Cloud</td><td>Organization</td><td>Folders</td><td>Project (billing, quotas)</td><td>IAM policy (additive)</td></tr><tr><td>AWS</td><td>Organization root</td><td>Organizational Units</td><td>Account (billing, isolation)</td><td>SCPs (ceilings)</td></tr><tr><td>Azure</td><td>Tenant root</td><td>Management Groups</td><td>Subscription (billing)</td><td>Azure Policy + RBAC</td></tr></tbody></table><p>Recurring properties: the middle is untyped and recursive (customers model themselves), exactly one node kind is promoted (where billing and isolation anchor), policy attaches to nodes and inherits downward, and every vendor caps nesting depth. The clouds disagree on inheritance mood: GCP IAM is additive-only (children gain, never lose), AWS SCPs are ceilings (ancestors bound children). Permissions and limits inherit in opposite moods, and a design needs both.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>Chosen option: one hierarchy of untyped nodes per tenant, because it is the only pattern that survived at scale across three independent cloud vendors, and it removes every platform guess about tenant org charts.</p><p><strong>A node is a named position in the tenant&#39;s tree, not a thing.</strong> Nothing is stored inside one; resources attach to it.</p><p>The decision, five rules:</p><ol><li>Each tenant has one tree of nodes. A node is an opaque id. The tree changes only through three audited operations (add, move, remove), each validated against the whole tree (parent exists, no cycles, depth cap of 10). There is no node record; the current tree is derived from the history of those operations.</li><li>Every resource carries exactly one node id: the node it is attached to, spelled <code>parent</code> on the resource per <a href="./../6310044131/README.html">ADR#6310044131</a> and typed as <code>trogon.hierarchy.v1alpha1.NodeId</code>. It is the only position field, and it is mandatory. A resource-level <code>owner</code> field is not required and is not the default; see &quot;Ownership follows the hierarchy&quot; below.</li><li>The platform never interprets what a node <em>means</em>. Words like &quot;project&quot; or &quot;team&quot; are labels on the id; display names are API-surface slugs. No code path is conditioned on them.</li><li><strong>Finding walks up.</strong> Looking up a resource by name searches the starting node, then its ancestors toward the root; the nearest match wins.</li><li><strong>Rules flow down.</strong> A policy attached to a node governs everything at or below it. Permissions accumulate downward (a child can gain, never lose); limits bound downward (a parent caps everything below).</li></ol><h3 id="ownership-follows-the-hierarchy" tabindex="-1">Ownership follows the hierarchy <a class="header-anchor" href="#ownership-follows-the-hierarchy" aria-label="Permalink to &quot;Ownership follows the hierarchy&quot;">​</a></h3><p>A resource whose <code>parent</code> is <code>node_01h9x</code>, the node a tenant labels its billing project, is answered for by whoever answers for that node. Nothing has to be copied onto the resource for that to be true, because the attachment was authorized against that node in the first place: the write path establishes that the calling principal may attach a resource there, and the principal accountable for the node is accountable for what hangs off it. Adding an <code>owner</code> field to restate that is counterproductive:</p><ol><li><strong>It duplicates a fact the node already carries.</strong> Two records of one truth diverge, and the copy is the one that goes stale, so reads have to pick a winner that no rule names.</li><li><strong>It re-asks a question authorization already answered.</strong> The attach check is where a principal is bound to a node. A field written after that check reflects it at one instant and stops tracking.</li><li><strong>It makes routine governance changes lossy.</strong> Reorganizing the tree, or moving a resource to a different node, re-anchors accountability by design; the audited tree operation is the record of that change. A stored owner survives the move unchanged and quietly becomes wrong.</li></ol><p>The rules that follow, stated as bullets so that the numbered references in this ADR always mean the five rules of the decision above:</p><ul><li><strong>No owner field by default.</strong> Resources carry <code>parent</code>. A schema <strong>SHOULD NOT</strong> add an <code>owner</code> merely to make ownership look explicit.</li><li><strong>The answer lives with the node.</strong> Who answers for a node is authorization data, resolved in the authorization system exactly like membership, never stored in the tree; rule 1 leaves nodes as bare ids for exactly this reason.</li><li><strong>Resolution walks up</strong>, in the mood of rule 4: the nearest ancestor with an accountable principal wins, and the tenant root always has one. Every resource therefore resolves to exactly one answer, including a resource sitting at the root. That is the guarantee a mandatory <code>owner</code> column used to buy, now bought without the stale copy.</li><li><strong>An owner field is an exception record.</strong> A resource-level <code>owner</code><strong>MAY</strong> exist only where the accountable principal genuinely differs from what walking up resolves. It carries no other meaning, so writing one that agrees with the resolved answer is a review defect, and the exception is worth a comment saying why the node is not the right anchor.</li><li><strong>A recurring exception is a position problem.</strong> If a resource needs a different accountable party often enough to feel like a pattern, it belongs at a different node; the schema does not need a field.</li></ul><p>What a position still does <strong>not</strong> decide, because these are other axes:</p><ul><li><strong>Permission.</strong> A <code>parent</code> value is not itself a grant. Policy attached to the node is evaluated per rule 5; the field records which node the resource is attached to, and authorization reads it as input rather than treating it as an answer.</li><li><strong>Mutation authority.</strong> Whether a row is converged by the system or written by principals is <code>managed_by</code>, per <a href="./../8779742261/README.html">ADR#8779742261</a>, which is orthogonal to both position and ownership and reserves <code>owner</code>/<code>owned_by</code> for the belonging sense used here.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>&quot;What is attached to this node?&quot; is a query over resource pointers; the tree itself stores nothing.</li><li>Who belongs to a node (membership) is authorization data, kept in the authorization system, not in the tree.</li><li>&quot;Who answers for this resource?&quot; is answered from its node, so the answer stays correct through reorganizations without a migration or a backfill of owner columns.</li><li>Moving a node is one audited operation; ids never change, so nothing that references a node breaks. Policies apply from the new position going forward.</li><li>If the platform ever needs to treat one kind of node specially (for example, billing per &quot;project&quot;), that kind is promoted to a real concept at that moment, by a new decision. Until then, everything stays a label.</li><li>How each service stores the tree history (event stream, audited table) is that service&#39;s implementation choice.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../6310044131/README.html">ADR#6310044131</a>: Hierarchy position is referenced by a bare parent field</li><li><a href="./../8779742261/README.html">ADR#8779742261</a>: Actor and Authority Taxonomy for Managed Systems</li><li><a href="https://github.com/TrogonStack/trogon-proto/blob/main/proto/trogon/hierarchy/v1alpha1/node.proto" target="_blank" rel="noreferrer"><code>trogon.hierarchy.v1alpha1.NodeId</code></a></li><li><a href="https://cloud.google.com/resource-manager/docs/cloud-platform-resource-hierarchy" target="_blank" rel="noreferrer">Google Cloud resource hierarchy (Folders)</a></li><li><a href="https://docs.aws.amazon.com/organizations/latest/userguide/orgs_manage_ous.html" target="_blank" rel="noreferrer">AWS Organizations: Organizational Units</a></li><li><a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Azure management groups</a></li><li><a href="https://research.google/pubs/pub48190/" target="_blank" rel="noreferrer">Zanzibar: Google&#39;s Consistent, Global Authorization System</a></li><li><a href="https://github.com/kubernetes-sigs/hierarchical-namespaces" target="_blank" rel="noreferrer">Kubernetes Hierarchical Namespace Controller</a></li><li><a href="https://google.aip.dev/122" target="_blank" rel="noreferrer">Google AIP-122: Resource names</a> / <a href="https://google.aip.dev/124" target="_blank" rel="noreferrer">AIP-124: Resource association</a></li></ul>',34)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
